// Публичные адреса и ожидаемые ответы. Код 401 у API — признак, что приложение живо и требует входа.
const c = $input.first().json;
const checks = [
  { key: 'panel',      name: 'Панель: страница входа',          url: c.panelBase + '/admin/login',        expect: [200] },
  { key: 'panel-api',  name: 'API панели (без входа → 401)',    url: c.panelBase + '/api/admin/dashboard', expect: [401] },
  { key: 'miniapp',    name: 'Mini App',                        url: c.panelBase + '/miniapp',            expect: [200] },
  { key: 'mini-api',   name: 'API Mini App (без подписи → 401)', url: c.panelBase + '/api/miniapp/clinic', expect: [401] },
  { key: 'ru-miniapp', name: 'Mini App через прокси в РФ',      url: c.ruProxyBase + '/miniapp',          expect: [200] },
];
return checks.filter((x) => x.url.startsWith('https://')).map((json) => ({ json }));

// Сравнивает ответы с ожидаемыми, хранит состояние между запусками (staticData).
// Тревога после failAfter неудач подряд, напоминание раз в remindHours, затем «Восстановлено».
const cfg = $('Настройки мониторинга').first().json;
const checks = $('Список проверок').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
const state = $getWorkflowStaticData('global');
state.checks = state.checks || {};
const now = Date.now();
const alerts = [], recovered = [];
checks.forEach((check, idx) => {
  const r = results[idx] || {};
  const code = typeof r.statusCode === 'number' ? r.statusCode : null;
  const ok = code !== null && check.expect.includes(code);
  const reason = code === null ? 'нет ответа' + (r.error ? ': ' + String(r.error.message || r.error).slice(0, 120) : '') : 'код ' + code + ', ожидался ' + check.expect.join('/');
  const s = state.checks[check.key] || { fails: 0, alertedAt: 0, since: 0 };
  if (ok) {
    if (s.alertedAt) recovered.push('✅ ' + check.name + ' — восстановлено, сбой ' + Math.round((now - s.since) / 60000) + ' мин');
    state.checks[check.key] = { fails: 0, alertedAt: 0, since: 0 };
    return;
  }
  s.fails += 1;
  if (!s.since) s.since = now;
  const due = s.fails >= cfg.failAfter && (!s.alertedAt || now - s.alertedAt >= cfg.remindHours * 3600000);
  if (due) { alerts.push('• ' + check.name + ': ' + reason); s.alertedAt = now; }
  state.checks[check.key] = s;
});
const lines = [];
if (alerts.length) lines.push('⚠️ «Демо-Мед»: проблема доступности', ...alerts);
if (recovered.length) lines.push(...recovered);
return [{ json: { notify: lines.length > 0, text: lines.join('\n'), checked: checks.length, failing: Object.values(state.checks).filter((s) => s.fails > 0).length } }];

const e = $input.first().json;
const node = e.execution?.lastNodeExecuted || 'неизвестный узел';
const msg = String(e.execution?.error?.message || 'без описания').slice(0, 300);
return [{ json: { text: '⚠️ n8n «Демо-Мед»: ошибка в узле «' + node + '»: ' + msg } }];

